["{
  "claims": [
    {"id": 1, "text": "Clinic notes and structured EHR medication histories often contain different medication information.", "poster_quote": "Clinic notes and structured EHR medication histories often contain different medication information."},
    {"id": 2, "text": "Discrepancies may arise from normalization errors, terminology differences, or documentation timing.", "poster_quote": "Discrepancies may arise from normalization errors, terminology differences, or documentation timing."},
    {"id": 3, "text": "This study develops a note-grounded evaluation framework using LLM-assisted reference construction, human review, deterministic normalization, and semantic-temporal comparison with structured records.", "poster_quote": "This study develops a note-grounded evaluation framework using LLM-assisted reference construction, human review, deterministic normalization, and semantictemporal comparison with structured records."},
    {"id": 4, "text": "The goal is to characterize the nature of mismatches rather than treat them as simple errors.", "poster_quote": "The goal is to characterize the nature of mismatches rather than treat them as simple errors."},
    {"id": 5, "text": "We used a frozen cohort of 11,812 visits from 761 patients.", "poster_quote": "We used a frozen cohort of 11,812 visits from 761 patients."},
    {"id": 6, "text": "31,282 candidate medication mentions were extracted from 22,483 clinic notes.", "poster_quote": "31,282 candidate medication mentions from 22,483 clinic notes."},
    {"id": 7, "text": "An LLM (Qwen2.5-32B-Instruct) generated initial canonical labels under deterministic decoding.", "poster_quote": "An LLM (Qwen2.5-32B-Instruct) generated initial canonical labels under deterministic decoding."},
    {"id": 8, "text": "Canonical labels were refined via human audit (targeted and random).", "poster_quote": "Canonical labels were refined via human audit (targeted and random)."},
    {"id": 9, "text": "Normalization performance was evaluated on a held-out test set of 5,403 mention rows from 150 patients.", "poster_quote": "We evaluated normalization performance on a held-out test set of 5,403 mention rows from 150 patients."},
    {"id": 10, "text": "The pipeline included surface-exact matching, lexical cleanup, curated alias mapping, and safe decomposition.", "poster_quote": "The pipeline included surface-exact matching, lexical cleanup, curated alias mapping, and safe decomposition."},
    {"id": 11, "text": "Note-derived labels were compared with structured EHR using a semantic-temporal ladder: exact, ingredient, broad-category, and ±30/±90-day temporal windows.", "poster_quote": "We compared note-derived labels with structured EHR using a semantictemporal ladder: exact, ingredient, broad-category, and ±30/±90-day temporal windows."},
    {"id": 12, "text": "OMOP/RxNorm mappings were used for sensitivity analysis.", "poster_quote": "OMOP/RxNorm mappings were used for sensitivity analysis."},
    {"id": 13, "text": "Low same-visit exact agreement does not imply documentation failure.", "poster_quote": "Low same-visit exact agreement does not imply documentation failure."},
    {"id": 14, "text": "Most mismatches reflect semantic relatedness or temporal displacement, not irreducible discordance.", "poster_quote": "Most mismatches reflect semantic relatedness or temporal displacement, not irreducible discordance."},
    {"id": 15, "text": "Note-side normalization errors and terminology gaps are major contributors to mismatches.", "poster_quote": "Note-side normalization errors and terminology gaps are major contributors."},
    {"id": 16, "text": "The deterministic pipeline’s gain came from institution-specific alias coverage, not generic matching.", "poster_quote": "The deterministic pipeline’s gain came from institution-specific alias coverage, not generic matching."},
    {"id": 17, "text": "MedXN comparison confirmed that treatment-context evidence requires controlled false positives.", "poster_quote": "MedXN comparison confirmed that treatment-context evidence requires controlled false positives."},
    {"id": 18, "text": "Manual review showed 80% of strict no-overlap cases were note-side mapping failures, not undocumented events.", "poster_quote": "Manual review showed 80% of strict no-overlap cases were noteside mapping failures, not undocumented events."},
    {"id": 19, "text": "Limitations include single-center data and LLM-assisted reference construction.", "poster_quote": "Limitations include single-center data and LLM-assisted reference construction."},
    {"id": 20, "text": "Exact canonical agreement improved from 0.7226 (surface-exact) to 0.8429 after lexical cleanup and alias mapping.", "poster_quote": "Exact canonical agreement improved from 0.7226 (surface-exact) to 0.8429 after lexical cleanup and alias mapping."},
    {"id": 21, "text": "Random audit of unaudited rows showed 0.9210 canonical agreement among valid mentions.", "poster_quote": "Random audit of unaudited rows showed 0.9210 canonical agreement among valid mentions."},
    {"id": 22, "text": "Treatment-action attribution was lower at 0.5326.", "poster_quote": "Treatment-action attribution was lower at 0.5326."},
    {"id": 23, "text": "Only 16.44% of note-derived rows had same-visit exact overlap with structured records.", "poster_quote": "Only 16.44% of note-derived rows had same-visit exact overlap with structured records."},
    {"id": 24, "text": "55.17% of note-derived rows had same-visit semantic overlap with structured records.", "poster_quote": "55.17% had same-visit semantic overlap."},
    {"id": 25, "text": "90.34% of note-derived rows had overlap within ±30 days.", "poster_quote": "90.34% had overlap within ±30 days."},
    {"id": 26, "text": "Under broad mapping, only 3.97% of note-derived rows remained in the strict no-overlap bucket.", "poster_quote": "Under broad mapping, only 3.97% remained in the strict no-overlap bucket."},
    {"id": 27, "text": "OMOP-backed sensitivity analysis showed strict no-overlap fell from 43.99% to 36.68% after alias supplement.", "poster_quote": "OMOP-backed sensitivity analysis showed strict no-overlap fell from 43.99% to 36.68% after alias supplement."},
    {"id": 28, "text": "Residual errors were mostly due to missing aliases (89.32%) and a small set of recurring terms (e.g., acetaminophen, oxycodone).", "poster_quote": "Residual errors were mostly due to missing aliases (89.32%) and a small set of recurring terms (e.g., acetaminophen, oxycodone)."},
    {"id": 29, "text": "Deterministic alias-aware normalization improved exact agreement from 0.7226 to 0.8429 on held-out patients.", "poster_quote": "On held-out patients, deterministic alias-aware normalization improved exact agreement from 0.7226 to 0.8429."},
    {"id": 30, "text": "Semantic-temporal analysis revealed that mismatches often reflect terminology, timing, or mapping limits—not missing medication events.", "poster_quote": "Semantictemporal analysis revealed that mismatches often reflect terminology, timing, or mapping limits—not missing medication events."},
    {"id": 31, "text": "This approach enables evidence characterization before clinical inference, improving reliability when comparing clinic notes with structured EHR data.", "poster_quote": "This approach enables evidence characterization before clinical inference, improving reliability when comparing clinic notes with structured EHR data."},
    {"id": 32, "text": "Future work should test portability across institutions and extend to other treatment-context entities.", "poster_quote": "Future work should test portability across institutions and extend to other treatmentcontext entities."}
  ]
